const home=document.getElementById('home-view'),order=document.getElementById('order-view'),form=document.getElementById('order-form'),summary=document.getElementById('summary'),service=document.getElementById('service');
const hints={'Dokumen & Penulisan':'Sertakan jumlah halaman, draft yang tersedia, dan pedoman format.','PPT & Presentasi':'Sertakan materi sumber, jumlah slide, dan gaya desain yang kamu suka.','Coding & Website':'Jelaskan tujuan, fitur yang diperlukan, serta kode atau referensi yang tersedia.','Bantuan & Review Tugas':'Sertakan mata pelajaran/kuliah dan bagian yang ingin dibahas atau diperiksa.'};
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'start_order_preview',title:'Buka contoh formulir pesanan',description:'Membuka formulir simulasi Techrey Digital untuk layanan pilihan. Tidak membuat pesanan atau pembayaran.',inputSchema:{type:'object',properties:{service:{type:'string',enum:Object.keys(hints)}},required:['service'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.service!=='string'||!Object.hasOwn(hints,input.service))throw new Error('Layanan tidak tersedia.');service.value=input.service;hint();form.hidden=false;summary.hidden=true;location.hash='pesan';showRoute();return{view:'order-preview',service:service.value,submitted:false};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
function hint(){document.getElementById('service-hint').textContent=hints[service.value]||'Sertakan format hasil dan referensi jika ada.';}
function showRoute(){const isOrder=location.hash==='#pesan';home.hidden=isOrder;order.hidden=!isOrder;if(isOrder){document.title='Ajukan Kebutuhan — Techrey Digital';window.scrollTo(0,0);}else{document.title='Techrey Digital — Ide kamu, kita wujudkan.';const id=location.hash.slice(1);if(id)requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView());}}
document.querySelectorAll('[data-order]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.order)service.value=button.dataset.order;hint();form.hidden=false;summary.hidden=true;location.hash='pesan';showRoute();}));
document.getElementById('back-home').addEventListener('click',()=>location.hash='beranda');window.addEventListener('hashchange',showRoute);service.addEventListener('change',hint);showRoute();
const deadline=document.getElementById('deadline');deadline.min=new Date(Date.now()+8*3600000).toISOString().slice(0,16);
const file=document.getElementById('file'),fileName=document.getElementById('file-name');file.addEventListener('change',()=>{const chosen=file.files[0];if(chosen&&chosen.size>10*1024*1024){file.value='';fileName.textContent='File terlalu besar. Pilih file maksimal 10 MB.';fileName.classList.add('error-text');}else{fileName.classList.remove('error-text');fileName.textContent=chosen?chosen.name+' · hanya dipilih di perangkatmu':'PDF, Word, PPT, gambar, atau ZIP · maks. 10 MB';}});
form.addEventListener('submit',event=>{event.preventDefault();if(new Date(deadline.value+'+08:00')<=new Date()){deadline.setCustomValidity('Pilih tenggat setelah waktu sekarang.');deadline.reportValidity();return;}deadline.setCustomValidity('');summary.replaceChildren();const check=document.createElement('div');check.className='summary-check';check.textContent='✓';summary.append(check);const title=document.createElement('h3');title.textContent='Begini ringkasan pesananmu.';summary.append(title);const intro=document.createElement('p');intro.textContent='Dalam web yang aktif, kebutuhan ini akan ditinjau sebelum penawaran dikirim. Ini hanya contoh dan belum menjadi pesanan.';summary.append(intro);const dl=document.createElement('dl');dl.className='summary-list';const data=[['Layanan',service.value],['Proyek',document.getElementById('title').value],['Nama',document.getElementById('name').value],['WhatsApp',document.getElementById('contact').value],['Keperluan',document.getElementById('purpose').value],['Brief',document.getElementById('brief').value],['Tenggat',deadline.value.replace('T',' · ')+' WITA'],['Anggaran',document.getElementById('budget').value?new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(document.getElementById('budget').value)):'Belum ditentukan'],['Lampiran',file.files[0]?.name||'Tidak ada'],['Pembayaran','QRIS — setelah penawaran disetujui']];for(const [label,value]of data){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);dl.append(row);}summary.append(dl);const note=document.createElement('p');note.className='prototype-note';note.textContent='Simulasi selesai. Tidak ada data yang dikirim, file yang diunggah, atau pembayaran yang dilakukan.';summary.append(note);const actions=document.createElement('div');actions.className='summary-actions';const edit=document.createElement('button');edit.className='button secondary';edit.textContent='Ubah detail';edit.addEventListener('click',()=>{form.hidden=false;summary.hidden=true;});const back=document.createElement('button');back.className='button';back.textContent='Kembali ke beranda ↗';back.addEventListener('click',()=>location.hash='beranda');actions.append(edit,back);summary.append(actions);form.hidden=true;summary.hidden=false;document.querySelector('.form-card').scrollIntoView({block:'start'});});deadline.addEventListener('input',()=>deadline.setCustomValidity(''));
